// Audibles Länder-Marktplätze; absichtlich keine Freigabe für beliebige Websites.
export const AUDIBLE_DOMAINS = [
  'audible.de', 'audible.com', 'audible.co.uk', 'audible.ca', 'audible.com.au',
  'audible.fr', 'audible.co.jp', 'audible.it', 'audible.in', 'audible.es', 'audible.com.br',
] as const;

export function isSupportedPlayer(url: URL): boolean {
  const hostname = url.hostname.replace(/^www\./, '');
  return url.protocol === 'https:'
    && AUDIBLE_DOMAINS.some(domain => domain === hostname)
    && /^\/webplayer\/?$/.test(url.pathname);
}
