import { getExtensionApi } from './extension-api';

const STORAGE_KEY = 'volume';
const HOST_ID = 'nerzors-audible-volume';

function isVolume(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1;
}

export async function startVolumeControl(styles: string, darkStyles = ''): Promise<() => void> {
  const extensionApi = getExtensionApi();
  let preferredVolume: number | undefined;
  let muted = false;
  let darkMode = false;
  let lastAudibleVolume = 1;
  let storageError = false;
  try {
    const stored = await extensionApi.storage.local.get([STORAGE_KEY, 'muted', 'darkMode', 'lastAudibleVolume']);
    if (isVolume(stored[STORAGE_KEY])) preferredVolume = stored[STORAGE_KEY];
    muted = stored.muted === true;
    darkMode = stored.darkMode === true;
    if (isVolume(stored.lastAudibleVolume) && stored.lastAudibleVolume > 0) lastAudibleVolume = stored.lastAudibleVolume;
    else if (preferredVolume && preferredVolume > 0) lastAudibleVolume = preferredVolume;
  } catch {
    storageError = true;
  }

  const host = document.createElement('div');
  host.id = HOST_ID;
  host.lang = extensionApi.i18n.getMessage('localeCode');
  const root = host.attachShadow({ mode: 'open' });
  const style = document.createElement('style');
  style.textContent = styles;
  const row = document.createElement('div');
  row.className = 'volume';
  const label = document.createElement('label');
  label.className = 'sr-only';
  label.htmlFor = 'volume';
  label.textContent = extensionApi.i18n.getMessage('volumeLabel');
  const slider = document.createElement('input');
  slider.id = 'volume';
  slider.type = 'range';
  slider.min = '0';
  slider.max = '100';
  slider.step = '1';
  const output = document.createElement('output');
  output.htmlFor = 'volume';
  const muteButton = document.createElement('button');
  muteButton.type = 'button';
  muteButton.id = 'mute';
  const themeButton = document.createElement('button');
  themeButton.type = 'button';
  themeButton.id = 'theme';
  const pageStyle = document.createElement('style');
  pageStyle.id = 'nerzors-player-theme';
  pageStyle.textContent = darkStyles;
  document.head.append(pageStyle);
  const status = document.createElement('p');
  status.className = 'status';
  status.id = 'status';
  status.setAttribute('role', 'status');
  slider.setAttribute('aria-describedby', 'status');
  row.append(label, muteButton, slider, output, themeButton);
  root.append(style, row, status);

  const boundAudio = new Map<HTMLAudioElement, () => void>();
  let frame: number | undefined;
  let saveTimer: ReturnType<typeof setTimeout> | undefined;
  let updatingAudio = false;

  function applyAudio(audio: HTMLAudioElement) {
    updatingAudio = true;
    try {
      if (preferredVolume !== undefined) audio.volume = preferredVolume;
      audio.muted = muted;
    } finally { updatingAudio = false; }
  }

  function setIcon(button: HTMLButtonElement, paths: string[], sun = false) {
    const namespace = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(namespace, 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('aria-hidden', 'true');
    if (sun) {
      const circle = document.createElementNS(namespace, 'circle');
      circle.setAttribute('cx', '12');
      circle.setAttribute('cy', '12');
      circle.setAttribute('r', '4');
      svg.append(circle);
    }
    for (const data of paths) {
      const path = document.createElementNS(namespace, 'path');
      path.setAttribute('d', data);
      svg.append(path);
    }
    button.replaceChildren(svg);
  }

  function updateMuteButton() {
    const silent = muted || preferredVolume === 0;
    const text = extensionApi.i18n.getMessage(silent ? 'unmute' : 'mute');
    muteButton.title = text;
    muteButton.setAttribute('aria-label', text);
    muteButton.setAttribute('aria-pressed', String(silent));
    setIcon(muteButton, ['M11 5 6 9H3v6h3l5 4Z', silent
      ? 'm16 9 6 6m0-6-6 6'
      : 'M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14']);
  }

  function applyTheme() {
    document.documentElement.toggleAttribute('data-nerzors-dark', darkMode);
    host.toggleAttribute('data-dark', darkMode);
    const text = extensionApi.i18n.getMessage(darkMode ? 'lightMode' : 'darkMode');
    themeButton.title = text;
    themeButton.setAttribute('aria-label', text);
    themeButton.setAttribute('aria-pressed', String(darkMode));
    setIcon(themeButton, [darkMode
      ? 'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5'
      : 'M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z'], darkMode);
  }

  function render(value: number) {
    const percent = Math.round(value * 100);
    slider.value = String(percent);
    slider.style.setProperty('--volume-progress', `${percent}%`);
    slider.setAttribute('aria-valuetext', extensionApi.i18n.getMessage('volumeAccessibleValue', String(percent)));
    output.value = extensionApi.i18n.getMessage('volumePercent', String(percent));
    updateMuteButton();
  }

  function updateStatus() {
    slider.disabled = boundAudio.size === 0;
    muteButton.disabled = slider.disabled;
    status.textContent = boundAudio.size === 0
      ? extensionApi.i18n.getMessage('waitingForAudio')
      : storageError ? extensionApi.i18n.getMessage('storageError') : '';
  }

  function sync() {
    frame = undefined;
    const controls = document.querySelector('[data-testid="previous-section"]')?.parentElement;
    if (controls && !document.getElementById(HOST_ID)) controls.after(host);
    // Audible kann die komplette Steuerung ersetzen und unseren Knoten entfernen.
    else if (controls && host.previousElementSibling !== controls) controls.after(host);

    for (const [audio, cleanup] of boundAudio) {
      if (!audio.isConnected) { cleanup(); boundAudio.delete(audio); }
    }
    for (const audio of document.querySelectorAll('audio')) {
      if (boundAudio.has(audio)) continue;
      if (preferredVolume === undefined) {
        preferredVolume = audio.volume;
        if (preferredVolume > 0) lastAudibleVolume = preferredVolume;
      }
      const apply = () => {
        applyAudio(audio);
      };
      const reflect = () => {
        if (updatingAudio || !audio.isConnected) return;
        preferredVolume = audio.volume;
        muted = audio.muted;
        if (audio.volume > 0) lastAudibleVolume = audio.volume;
        render(audio.volume);
      };
      audio.addEventListener('loadedmetadata', apply);
      audio.addEventListener('play', apply);
      audio.addEventListener('volumechange', reflect);
      boundAudio.set(audio, () => {
        audio.removeEventListener('loadedmetadata', apply);
        audio.removeEventListener('play', apply);
        audio.removeEventListener('volumechange', reflect);
      });
      apply();
      render(audio.volume);
    }
    updateStatus();
  }

  async function save() {
    clearTimeout(saveTimer);
    try {
      await extensionApi.storage.local.set({
        ...(preferredVolume !== undefined ? { [STORAGE_KEY]: preferredVolume } : {}),
        muted, darkMode, lastAudibleVolume,
      });
      storageError = false;
    } catch {
      storageError = true;
    }
    updateStatus();
  }

  slider.addEventListener('input', () => {
    preferredVolume = Number(slider.value) / 100;
    if (preferredVolume > 0) { lastAudibleVolume = preferredVolume; muted = false; }
    for (const audio of boundAudio.keys()) applyAudio(audio);
    render(preferredVolume);
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => void save(), 200);
  });
  slider.addEventListener('change', () => void save());
  muteButton.addEventListener('click', () => {
    if (muted || preferredVolume === 0) {
      muted = false;
      if (preferredVolume === 0) preferredVolume = lastAudibleVolume;
    } else muted = true;
    for (const audio of boundAudio.keys()) applyAudio(audio);
    render(preferredVolume ?? 1);
    void save();
  });
  themeButton.addEventListener('click', () => {
    darkMode = !darkMode;
    applyTheme();
    void save();
  });

  const observer = new MutationObserver(() => {
    if (frame === undefined) frame = requestAnimationFrame(sync);
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });
  render(preferredVolume ?? 1);
  applyTheme();
  sync();

  return () => {
    observer.disconnect();
    if (frame !== undefined) cancelAnimationFrame(frame);
    clearTimeout(saveTimer);
    for (const cleanup of boundAudio.values()) cleanup();
    host.remove();
    pageStyle.remove();
    document.documentElement.removeAttribute('data-nerzors-dark');
  };
}
