import styles from './volume.scss?inline';
import { startVolumeControl } from './volume';
import darkStyles from './dark.scss?inline';
import { isSupportedPlayer } from './domains';

// Match patterns erlauben auch /webplayer-irgendwas: deshalb genauer prüfen.
if (isSupportedPlayer(new URL(location.href))) {
  void startVolumeControl(styles, darkStyles);
}
